/**
 * Python auth layer files (docs/backend/auth.md): rendered from `src/generator-assets/python-fastapi/auth/**` for the
 * picked modules (`applyAuthBlocks`). G files carry `# <auto-generated by Generator />` and follow
 * `workspace.auth.modules` on every generate; K files (hooks, custom routes / services) are written once.
 */
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'fs';
import { dirname, join, relative } from 'path';
import type { AuthModule } from '../../../shared/authModules.js';
import { applyAuthBlocks } from '../../utils/authBlocks.js';
import { withOnceHeader } from '../../utils/generatedFileOwnership.js';
import { listFiles, type WrittenFile } from '../dotnet-efcore/dotnetFiles.js';
import { applyPythonTokens, pythonAssetsDir } from './pythonFiles.js';
import { PYTHON_GENERATED_HEADER } from './pythonLayout.js';

const APP_NAME_TOKEN = '__App__';

/** K files, relative to `src/<pkg>/`. */
export const PYTHON_AUTH_OWNED: readonly string[] = ['modules/auth/hooks.py', 'modules/auth/router_custom.py', 'modules/auth/service_custom.py'];

/**
 * Removing module blocks leaves the blank lines ruff put around them: at most two blank lines in a row, one newline at
 * the end, and no blank line between two first-party imports (ruff isort keeps one block per section).
 */
export function tidyPython(text: string, pkg: string): string {
  const firstParty = (line: string) => line.startsWith(`from ${pkg}.`) || line.startsWith(`from ${pkg} `) || line.startsWith(`import ${pkg}`);
  const lines = text.split(/\r?\n/);
  const out: string[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.trim() === '') {
      const prev = out[out.length - 1];
      let j = i;
      while (j < lines.length && lines[j].trim() === '') j++;
      // A parenthesised import ends with `)`: look back to its `from` line.
      let k = out.length - 1;
      while (k >= 0 && (out[k].startsWith('    ') || out[k] === ')')) k--;
      if (prev !== undefined && k >= 0 && firstParty(out[k]) && j < lines.length && firstParty(lines[j])) {
        i = j - 1;
        continue;
      }
      if (out.length >= 2 && out[out.length - 1].trim() === '' && out[out.length - 2].trim() === '') continue;
    }
    out.push(line);
  }
  return `${out.join('\n').replace(/\s*$/, '')}\n`;
}

export interface PythonAuthFile {
  target: string;
  content: string;
  owned: boolean;
}

/** `retired`: G files of modules that are off (removed from the host when they carry the header). */
export function renderPythonAuthFiles(root: string, pkg: string, app: string, modules: readonly AuthModule[]): { files: PythonAuthFile[]; retired: string[] } {
  const dir = join(pythonAssetsDir(), 'auth');
  const files: PythonAuthFile[] = [];
  const retired: string[] = [];
  for (const file of listFiles(dir).filter((f) => !/[\\/]__pycache__[\\/]|\.pyc$/.test(f))) {
    const rel = relative(dir, file).replace(/\\/g, '/');
    const target = join(root, applyPythonTokens(rel, pkg));
    const owned = PYTHON_AUTH_OWNED.some((p) => rel === `src/__app__/${p}`);
    const content = applyAuthBlocks(readFileSync(file, 'utf8'), modules);
    if (content === null) {
      if (!owned) retired.push(target);
      continue;
    }
    const body = tidyPython(applyPythonTokens(content, pkg).split(APP_NAME_TOKEN).join(app), pkg);
    files.push({ target, owned, content: owned ? body : `${PYTHON_GENERATED_HEADER}\n${body}` });
  }
  return { files, retired };
}

/**
 * Plans (and with `apply` writes) the auth files. A G file without the header is the project's (`skipped-user-owned`),
 * unless its content is already the Generator's: then it gets the header (hosts made before auth G).
 */
export function syncPythonAuth(root: string, pkg: string, app: string, modules: readonly AuthModule[], apply: boolean): WrittenFile[] {
  const { files, retired } = renderPythonAuthFiles(root, pkg, app, modules);
  const changes: WrittenFile[] = [];
  const write = (path: string, content: string) => {
    if (!apply) return;
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content, 'utf8');
  };
  for (const { target, content, owned } of files) {
    if (!existsSync(target)) {
      write(target, owned ? withOnceHeader(target, content) : content);
      changes.push({ path: target, action: 'created' });
      continue;
    }
    if (owned) {
      changes.push({ path: target, action: 'skipped-exists' });
      continue;
    }
    const current = readFileSync(target, 'utf8');
    const ownedByGenerator = current.startsWith(PYTHON_GENERATED_HEADER) || current === content.slice(PYTHON_GENERATED_HEADER.length + 1);
    if (current === content) changes.push({ path: target, action: 'unchanged' });
    else if (!ownedByGenerator) changes.push({ path: target, action: 'skipped-user-owned' });
    else {
      write(target, content);
      changes.push({ path: target, action: 'updated' });
    }
  }
  for (const target of retired) {
    if (!existsSync(target)) continue;
    if (!readFileSync(target, 'utf8').startsWith(PYTHON_GENERATED_HEADER)) {
      changes.push({ path: target, action: 'skipped-user-owned' });
      continue;
    }
    if (apply) rmSync(target);
    changes.push({ path: target, action: 'removed' });
  }
  return changes;
}

/** K files the G files call into: a module turned on later needs its hook in the project's `hooks.py`. */
export function pythonAuthNotes(root: string, pkg: string, modules: readonly AuthModule[]): string[] {
  const hooks = join(root, 'src', pkg, 'modules', 'auth', 'hooks.py');
  if (!modules.includes('account-delete') || !existsSync(hooks) || /\bdef on_account_delete\b/.test(readFileSync(hooks, 'utf8'))) return [];
  return [
    `src/${pkg}/modules/auth/hooks.py: account-delete için 'async def on_account_delete(db: Any, user: dict[str, Any]) -> None' eklenmeli (kullanıcının kendi verisi burada silinir).`
  ];
}
